Record AM_frame (st st1 : mstate) : Prop := mkAMF {
  amf_groups : s_groups st1 = s_groups st;
  amf_slots : s_slots st1 = s_slots st;
  amf_shadow : s_shadow st1 = s_shadow st;
  amf_tick : s_tick st1 = s_tick st;
  amf_active : forall sc, active st1 sc = active st sc;
  amf_usage : forall sc, usage st1 sc = usage st sc;
  amf_bounces : c_bounces (s_ctx st1) = c_bounces (s_ctx st);
  amf_seq : c_seq (s_ctx st1) = c_seq (s_ctx st);
  amf_mc : c_mmap_counter (s_ctx st1) = c_mmap_counter (s_ctx st);
  amf_regions : forall rid r, s_regions st !! rid = Some r -> r_kind r = RKGroup -> s_regions st1 !! rid = Some r;
  amf_next_rid : (s_next_rid st <= s_next_rid st1)%N;
  amf_ssec : s_secret st1 = s_secret st
}.
Lemma amf_refl st : AM_frame st st.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 1 "S30!4'5+6'7+8'9!6':+6'7';+8'9'<!1'H#1$st;R+0!>,1#1#1!2,2!4+3'401+=!1'>#1!2,2!4+3'401!2+?'4+8!1'@#1!2,2!4+3+6'7';+A!1'B#1!2,2+6!1'C#1$sc;R+8!2,2'D!2'E#2#1$sc;R+8!2,2+8!2'F#2#1!2,2!4+3+8'9'<+8!1'G2!2,2+8!1'I2!2,2+8!1'J2$rid;R+6$r;R+K$H;R!3+L!1+M+K!6'N+6+K!4+3+6'7';+K!4'O+6'7';+K#2!1'P#3!2,Q+K#1$H0;R!3+L+R!1'S#2,T#2!4'U+6'V!3'W+6'V'X!1'Y#1!2,2+8!1'Z#1").
Qed.
Lemma amf_trans a b c : AM_frame a b -> AM_frame b c -> AM_frame a c.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 3 "SD0!4'5+6'7+8'9!6':+6'7';+8'9'<!4+3'401+=!4+3'401!2+?'4+8!4+3+6'7';+A!4+3+8'9'<+8!1+M+K!4+3+6'7';+K!4'O+6'7';+K!2,Q+K#1!3+L+R!1'S#2,T!2,Q+K#3!1'H#F!1'H#G!1'H#^1!1'H#^2!1'Z#^6!1'H#^6!1'H#^7!1'H#^8$a;R+0$b;R+0$c;R+0$H;R!2+[#3#2-[RN$~R!2+[#4#3%~R!2+[#4#3!2+[#6#4#11$amf_groups;R!3+L2!1'>#3!1'>#4$amf_slots;R!3+L3!1'@#4!1'@#5$amf_shadow;R!3+L4!1'B#5!1'B#6$amf_tick;R!3+L+6!1'C#6!1'C#7$amf_active;R%sc;R+8!3+L'D!2'E#8#1!2'E#9#1$amf_usage;R%sc;R+8!3+L+8!2'F#9#1!2'F#:#1$amf_bounces;R!3+L5!1'G!1'H#9!1'G!1'H#:$amf_seq;R!3+L+8!1'I!1'H#:!1'I!1'H#;$amf_mc;R!3+L+8!1'J!1'H#;!1'J!1'H#<$amf_regions;R%rid;R+6%r;R+K%~R!3+L6!6'N+6+K78#2!1'P#?9%~R:!3+L6!6'N+6+K78#4!1'P#@;$amf_next_rid;R!2'V!1'Y#>!1'Y#=$amf_ssec;R!3+L+8!1'Z#>!1'Z#?!<$A1;R!3+L2!1'>#?!1'>#@$A2;R!3+L3!1'@#@!1'@#A$A3;R!3+L4!1'B#A!1'B#B$A4;R!3+L+6!1'C#B!1'C#C$A5;R%sc;R+8!3+L'D!2'E#D#1!2'E#E#1$A6;R%sc;R+8!3+L+8!2'F#E#1!2'F#F#1$A7;R!3+L5!1'G!1'H#E!1'G<$A8;R!3+L+8!1'I<!1'I=$A9;R!3+L+8!1'J=!1'J!1'H#H$A10;R%rid;R+6%r;R+K%~R!3+L6!6'N+6+K78#2!1'P#K9%~R:!3+L6!6'N+6+K78#4!1'P#L;$A11;R!2'V!1'Y#J!1'Y#I$amf_ssec0;R!3+L+8!1'Z#J!1'Z#K$H;R!2+[#K#J-[RN$~R!2+[#L#K!2+[#N#L#11$amf_groups;R!3+L2!1'>#K!1'>#L$amf_slots;R!3+L3!1'@#L!1'@#M$amf_shadow;R!3+L4!1'B#M!1'B#N$amf_tick;R!3+L+6!1'C#N!1'C#O$amf_active;R%sc;R+8!3+L'D!2'E#P#1!2'E#Q#1$amf_usage;R%sc;R+8!3+L+8!2'F#Q#1!2'F#R#1$amf_bounces;R!3+L5!1'G!1'H#Q!1'G!1'H#R$amf_seq;R!3+L+8!1'I!1'H#R!1'I!1'H#S$amf_mc;R!3+L+8!1'J!1'H#S!1'J!1'H#T$amf_regions;R%rid;R+6%r;R+K%~R!3+L6!6'N+6+K78#2!1'P#W9%~R:!3+L6!6'N+6+K78#4!1'P#X;$amf_next_rid;R!2'V!1'Y#V!1'Y#U$amf_ssec;R!3+L+8!1'Z#V!1'Z#W!<$B1;R!3+L2!1'>#W!1'>#X$B2;R!3+L3!1'@#X!1'@#Y$B3;R!3+L4!1'B#Y!1'B#Z$B4;R!3+L+6!1'C#Z!1'C#[$B5;R%sc;R+8!3+L'D!2'E#\#1!2'E#^0#1$B6;R%sc;R+8!3+L+8!2'F#^0#1!2'F#^1#1$B7;R!3+L5!1'G!1'H#^0!1'G>$B8;R!3+L+8!1'I>!1'I?$B9;R!3+L+8!1'J?!1'J!1'H#^3$B10;R%rid;R+6%r;R+K%~R!3+L6!6'N+6+K78#2!1'P#^69%~R:!3+L6!6'N+6+K78#4!1'P#^7;$B11;R!2'V!1'Y#^5!1'Y#^4$amf_ssec1;R!3+L+8!1'Z#^5@!>,1#^8#^6!6'\2!1'>#^6!1'>#^7!1'>#^8#<#U!6'\3!1'@#^6!1'@#^7!1'@#^8#;#T!6'\4!1'B#^6!1'B#^7!1'B#^8#:#S!6'\+6!1'C#^6!1'C#^7!1'C#^8#9#R$sc;R+8!6'\'D!2'E#^7#1!2'E#^8#1!2'E#^9#1!1#9#1!1#R#1$sc;R+8!6'\+8!2'F#^7#1!2'F#^8#1!2'F#^9#1!1#8#1!1#Q#1!6'\5!1'GA!1'GB!1'GC#6#O!6'\+8!1'IA!1'IB!1'IC#5#N!6'\+8!1'JA!1'JB!1'JC#4#M$rid;R+6$r;R+K$H;R!3+L6!6'N+6+K78#2!1'P#^:9$K;R:!4#7#4#3!4#P#4#3#2#1#1!5'^0!1'Y#^8!1'Y#^7!1'Y#^6#K#2!6'\+8@!1'Z#^7!1'Z#^8#1#J#<#;#:#9#8#7#6#5#4#3#2#1#<#;#:#9#8#7#6#5#4#3#2#1").
