Record L_frame (L L1 : mled) : Prop := mkLF {
  lf_groups : ld_groups L1 = ld_groups L;
  lf_live : ld_live L1 = ld_live L;
  lf_resv : ld_resv L1 = ld_resv L
}.
Lemma lf_refl L : L_frame L L. Proof. ltac2:(Rpl.RP.run_i (rplG ()) 1 "S10!1+^3!2+?+8+8$L;R+^1!5,^2#1#1!2,20!1'^4#1!2,2!1+^3'^5!1'^6#1!2,20!1'^7#1").
