Theorem INVL_meta_adv : INVL X st' L' BL LS
  /\ c_avail_meta_areas (s_ctx st') = Some (aadd p 4096)
  /\ s_areas st' !! p = None /\ (forall k, 0 <= k < NSLOTS -> s_metas st' !! mslot p k = None)
